import numpy as np
from sklearn.decomposition import PCA, TruncatedSVD
from sklearn.preprocessing import StandardScaler, normalize
from sklearn.neighbors import NearestNeighbors
from scipy.optimize import minimize
from scipy.stats import poisson
from scipy.spatial import distance_matrix
from typing import *
from abc import ABC, abstractmethod

class SingleCellDenoiser(ABC):
    @abstractmethod
    def fit(self, X: np.ndarray) -> None:
        pass

    @abstractmethod
    def transform(self, X: np.ndarray) -> np.ndarray:
        pass

class Denoiser(SingleCellDenoiser):
    def __init__(self, n_components: int, max_iter: int = 1000, tol: float = 1e-6):
        self.n_components = n_components
        self.max_iter = max_iter
        self.tol = tol

    def fit(self, X: np.ndarray) -> None:
        self.pca_ = PCA(n_components=self.n_components)
        self.X_transformed = self.pca_.fit_transform(X)

    def transform(self, X: np.ndarray) -> np.ndarray:
        return self.pca_.transform(X)

class DenoiserVarianceStabilizer(Denoiser):
    def __init__(self, n_components: int, max_iter: int = 1000, tol: float = 1e-6, sqrt_transform: bool = True):
        super().__init__(n_components, max_iter, tol)
        self.sqrt_transform = sqrt_transform

    def fit(self, X: np.ndarray) -> None:
        super().fit(X)
        if self.sqrt_transform:
            self.mean_ = np.mean(X, axis=0)
            self.std_ = np.std(X, axis=0)
            self.X_transformed = (X - self.mean_) / self.std_

    def transform(self, X: np.ndarray) -> np.ndarray:
        if self.sqrt_transform:
            return (X - self.mean_) / self.std_
        return super().transform(X)

class DenoiserNormalizer(Denoiser):
    def __init__(self, n_components: int, max_iter: int = 1000, tol: float = 1e-6):
        super().__init__(n_components, max_iter, tol)

    def fit(self, X: np.ndarray) -> None:
        self.normalizer_ = StandardScaler()
        self.normalizer_.fit(X)
        self.X_transformed = self.normalizer_.transform(X)

    def transform(self, X: np.ndarray) -> np.ndarray:
        return self.normalizer_.transform(X)

class DenoiserNeighborhood(NearestNeighbors):
    def __init__(self, n_neighbors: int):
        super().__init__(n_neighbors=n_neighbors)

    def transform(self, X: np.ndarray) -> np.ndarray:
        return self.kneighbors(X)

class DenoiserPoissonLoss(Denoiser):
    def __init__(self, penalty: float = 1.0, epsilon: float = 1e-6):
        self.penalty = penalty
        self.epsilon = epsilon

    def fit(self, X: np.ndarray) -> None:
        self.X = X

    def transform(self, X: np.ndarray) -> np.ndarray:
        poisson_loss = self._calculate_poisson_loss(X)
        return X + self.penalty * poisson_loss

    def _calculate_poisson_loss(self, X: np.ndarray) -> np.ndarray:
        p = poisson.pmf(X.ravel(), np.exp(-self.X.sum(axis=-1)))
        p = p.reshape(*X.shape)
        loss = (-p + X.ravel())**2 / p + np.log(p)
        return loss

class MagicDenoiser(Denoiser):
    def __init__(self, n_components: int, max_iter: int = 1000, tol: float = 1e-6):
        super().__init__(n_components, max_iter, tol)

    def fit(self, X: np.ndarray) -> None:
        self.X_transformed = DenoiserVarianceStabilizer(n_components=self.n_components).fit_transform(X)

    def transform(self, X: np.ndarray) -> np.ndarray:
        transformed = self.X_transformed.copy()
        neighbors = DenoiserNeighborhood(n_neighbors=self.n_components).fit_transform(X.T).T
        for i in range(X.shape[0]):
            for j in range(X.shape[1]):
                if X[i,j] == 0:
                    distances = np.abs(neighbors[:,j] - transformed[:,i])
                    closest_neighbour_index = np.argmin(distances)
                    transformed[i,j] = transformed[closest_neighbour_index,j]
        return transformed

def evaluate_mse_func(X_train: np.ndarray, y_train: np.ndarray, X_test: np.ndarray, y_test: np.ndarray):
    mse = np.mean((X_test - y_test)**2)
    print(f"MSE: {mse}")
    return mse

def evaluate_poisson_func(X_train: np.ndarray, y_train: np.ndarray, X_test: np.ndarray, y_test: np.ndarray):
    poisson_loss_train = sum(X_train[y_train > 0] * np.log(y_train[y_train > 0])) / np.sum(X_train[y_train > 0])
    poisson_loss_test = sum(X_test[y_test > 0] * np.log(y_test[y_test > 0])) / np.sum(X_test[y_test > 0])
    print(f"Poisson Loss (Train): {poisson_loss_train}, (Test): {poisson_loss_test}")
    return poisson_loss_train, poisson_loss_test

# Example usage
