y = np.array([2, 3])

denoiser = MagicDenoiser(n_components=2)
denoiser.fit(X)
X_denoised = denoiser.transform(X)

evaluate_mse_func(X, y, X_denoised, y)
evaluate_poisson_func(X, y, X_denoised, y)

